# tools.py: Scout's six tools, working on fake data you control
import json
import re
from pathlib import Path

HERE = Path(__file__).parent
ORDERS = json.loads((HERE / "data" / "orders.json").read_text(encoding="utf-8"))
POLICY = (HERE / "docs" / "policy.md").read_text(encoding="utf-8")

# Stand-ins for Orbit's stock sheet and the ParcelPath tracking API
STOCK = {"TENT-2P-GRN": 4, "TENT-3P-GRN": 0, "BOOT-RDG-39": 2,
         "BOOT-RDG-38": 0, "JKT-STORM-M": 3, "JKT-STORM-L": 1}
PARCELS = {
    "PP-88213": {"status": "in transit", "last_scan": "Denver hub", "expected_delivery": "Thursday"},
    "PP-87102": {"status": "delivered", "delivered": "62 days ago"},
    "PP-90417": {"status": "in transit"},
    "PP-90955": {"status": "delivered", "delivered": "5 days ago"},
}
SLOW = {"PP-90417"}      # ParcelPath always times out on this one, so you can test errors


def get_order(order_id=None, email=None):
    if order_id:
        for order in ORDERS:
            if order["order_id"] == order_id.strip().upper():
                return order
        raise ValueError(f"No order with ID {order_id}")
    if email:
        found = [order for order in ORDERS if order["email"] == email.strip().lower()]
        if not found:
            raise ValueError(f"No orders for {email}")
        return {"orders": found}
    raise ValueError("Give an order_id or an email")


def track_parcel(tracking_number):
    if tracking_number in SLOW:
        raise TimeoutError("ParcelPath did not answer within 10 seconds. Do not retry; "
                           "tell the customer tracking is unavailable right now.")
    if tracking_number not in PARCELS:
        raise ValueError(f"Unknown tracking number {tracking_number}")
    return PARCELS[tracking_number]


def check_stock(sku):
    sku = sku.strip().upper()
    if sku not in STOCK:
        raise ValueError(f"Unknown SKU {sku}. SKUs look like JKT-STORM-M.")
    return {"sku": sku, "in_stock": STOCK[sku]}


# search_policy: the same as Module 4, sections of docs/policy.md scored by shared words
STOPWORDS = {"a", "an", "and", "are", "can", "do", "for", "i", "if", "in",
             "is", "it", "my", "of", "on", "or", "the", "to", "what", "you"}


def _words(text):
    return {w for w in re.findall(r"[a-z0-9]+", text.lower()) if w not in STOPWORDS}


def load_sections():
    """One chunk per '## ' heading in docs/policy.md, as (heading, text)."""
    sections, heading, lines = [], None, []
    for line in POLICY.splitlines():
        if line.startswith("## "):
            if heading:
                sections.append((heading, " ".join(lines)))
            heading, lines = line[3:].strip(), []
        elif heading and line.strip():
            lines.append(line.strip())
    if heading:
        sections.append((heading, " ".join(lines)))
    return sections


def search_policy(query, top=2):
    """The top sections that share the most words with the query."""
    query_words = _words(query)
    scored = []
    for heading, text in load_sections():
        score = len(query_words & _words(heading + " " + text))
        scored.append((score, heading, text))
    scored.sort(key=lambda s: s[0], reverse=True)
    best = [s for s in scored[:top] if s[0] > 0]
    if not best:
        return "No policy section matches that question."
    return "\n\n".join(f"## {heading}\n{text}" for score, heading, text in best)


def request_refund(order_id, amount, reason):
    order = get_order(order_id=order_id)
    if amount > order["total"]:
        raise ValueError(f"{amount} is more than the order total of {order['total']}")
    days = order["delivered_days_ago"]
    if days is not None and days > 30:
        raise ValueError(f"Delivered {days} days ago: outside the 30-day return window")
    if amount > 200:
        return {"status": "pending_approval", "order_id": order["order_id"], "amount": amount,
                "note": "Refunds over $200 must be approved by a member of the support team."}
    return {"status": "approved", "order_id": order["order_id"], "amount": amount,
            "note": "Goes back to the original payment method within 5 business days of the return arriving."}


HANDOFFS = []


def hand_off(summary):
    HANDOFFS.append(summary)
    return {"status": "handed_off", "ticket": f"HO-{1000 + len(HANDOFFS)}",
            "note": "A member of the support team will reply to the customer."}


