FUNCTIONS = {"get_order": get_order, "track_parcel": track_parcel, "check_stock": check_stock,
             "search_policy": search_policy, "request_refund": request_refund, "hand_off": hand_off}


def run_tool(name, tool_input):
    """Run the tool Scout asked for. Returns text: plain text as is, anything else as JSON."""
    if name not in FUNCTIONS:
        raise ValueError(f"Unknown tool: {name}")
    result = FUNCTIONS[name](**tool_input)
    return result if isinstance(result, str) else json.dumps(result)

# memory.py: the chat's recent turns, plus pinned facts that never fall out
import re

ORDER_ID = re.compile(r"\bORB-\d{5}\b", re.IGNORECASE)
EMAIL = re.compile(r"[\w.+-]+@[\w-]+(?:\.[\w-]+)+")
NAME = re.compile(r"\bmy name is ([A-Za-z]+)", re.IGNORECASE)


class Conversation:
    def __init__(self, max_turns=10):
        self.max_turns = max_turns  # customer turns kept in memory
        self.messages = []          # recent turns: the customer's text and Scout's replies
        self.facts = {}             # pinned facts: they survive trimming

    def add_user(self, text):
        """A message the customer typed. Key details are pinned as facts."""
        order = ORDER_ID.search(text)
        if order:
            self.facts["order_id"] = order.group(0).upper()
        email = EMAIL.search(text)
        if email:
            self.facts["email"] = email.group(0).lower()
        name = NAME.search(text)
        if name:
            self.facts["name"] = name.group(1).capitalize()
        self.messages.append({"role": "user", "content": text})
        self.trim()

    def add_assistant(self, text):
        """Scout's final reply. The tool calls behind it stay inside that run."""
        self.messages.append({"role": "assistant", "content": text})

    def pin(self, key, value):
        self.facts[key] = value

    def trim(self):
        """Keep only the last max_turns customer turns."""
        starts = [i for i, m in enumerate(self.messages) if m["role"] == "user"]
        if len(starts) > self.max_turns:
            self.messages = self.messages[starts[-self.max_turns]:]

    def system_prompt(self, base):
        """The base prompt plus the pinned facts."""
        if not self.facts:
            return base
        lines = "\n".join(f"- {key}: {value}" for key, value in self.facts.items())
        return f"{base}\n\nFacts about this customer (always use them):\n{lines}"
